  "misconceptions": {
    "LTR": {
      "student": "Worked left to right. Do × and ÷ before + and −.",
      "teacher": "Evaluates strictly left to right, ignoring precedence."
    },
    "ADD_FIRST": {
      "student": "Added or subtracted too early. × and ÷ come first.",
      "teacher": "Performs addition/subtraction before multiplication/division."
    },
    "IGNORE_PARENS": {
      "student": "Skipped the parentheses. Do what's inside them first.",
      "teacher": "Ignores grouping symbols and applies normal precedence to the flat expression."
    },
    "EXP_AS_MULT": {
      "student": "3² means 3 × 3, not 3 × 2.",
      "teacher": "Treats a^b as a × b."
    },
    "EXP_AFTER_MULT": {
      "student": "Exponent goes on its base only, before multiplying.",
      "teacher": "Evaluates exponents after multiplication/division, e.g. 2 × 3² as (2 × 3)²."
    },
    "M_BEFORE_D": {
      "student": "× and ÷ are a team: go left to right between them.",
      "teacher": "Reads PEMDAS literally and multiplies before dividing regardless of position."
    },
    "A_BEFORE_S": {
      "student": "+ and − are a team: go left to right between them.",
      "teacher": "Reads PEMDAS literally and adds before subtracting regardless of position."
    }
  },
